module adder_pipe_64bit (
    input clk,
    input rst_n,
    input i_en,
    input [63:0] adda,
    input [63:0] addb,
    output [64:0] result,
    output o_en
);

    // Pipeline registers for 16-bit sections of adda and addb
    reg [15:0] adda_reg[3:0];
    reg [15:0] addb_reg[3:0];

    // Pipeline registers for carry signals
    reg [16:0] carry_reg[3:0];

    // Output enable signal
    reg o_en_reg;

    // 65-bit wide adder for each pipeline stage
    wire [64:0] sum[3:0];
    assign sum[0] = {1'b0, adda_reg[0]} + {1'b0, addb_reg[0]};
    assign sum[1] = {1'b0, adda_reg[1]} + {1'b0, addb_reg[1]} + carry_reg[0][16];
    assign sum[2] = {1'b0, adda_reg[2]} + {1'b0, addb_reg[2]} + carry_reg[1][16];
    assign sum[3] = {1'b0, adda_reg[3]} + {1'b0, addb_reg[3]} + carry_reg[2][16];

    // Update pipeline registers
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            adda_reg[0] <= 16'b0;
            addb_reg[0] <= 16'b0;
            carry_reg[0] <= 17'b0;

            adda_reg[1] <= 16'b0;
            addb_reg[1] <= 16'b0;
            carry_reg[1] <= 17'b0;

            adda_reg[2] <= 16'b0;
            addb_reg[2] <= 16'b0;
            carry_reg[2] <= 17'b0;

            adda_reg[3] <= 16'b0;
            addb_reg[3] <= 16'b0;
            carry_reg[3] <= 17'b0;

            o_en_reg <= 1'b0;
        end else if (i_en) begin
            adda_reg[0] <= adda[15:0];
            addb_reg[0] <= addb[15:0];
            carry_reg[0] <= {1'b0, sum[0][64:0]};

            adda_reg[1] <= adda[31:16];
            addb_reg[1] <= addb[31:16];
            carry_reg[1] <= {1'b0, sum[1][64:0]};

            adda_reg[2] <= adda[47:32];
            addb_reg[2] <= addb[47:32];
            carry_reg[2] <= {1'b0, sum[2][64:0]};

            adda_reg[3] <= adda[63:48];
            addb_reg[3] <= addb[63:48];
            carry_reg[3] <= {1'b0, sum[3][64:0]};

            o_en_reg <= 1'b1;
        end else begin
            o_en_reg <= 1'b0;
        end
    end

    // Output result and o_en
    assign result = sum[3];
    assign o_en = o_en_reg;

endmodule
